import java.io.BufferedReader; import java.io.InputStreamReader; import java.util.StringTokenizer; public class TestClass { public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine().trim()); StringBuilder sb = new StringBuilder(); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); long n = Long.parseLong(st.nextToken()); long k = Long.parseLong(st.nextToken()); if (n == 1) { sb.append(1).append("\n"); continue; } long cycle = 2 * n - 2; long rem = k % cycle; if (rem == 0) { sb.append(2).append("\n"); } else if (rem <= n) { sb.append(rem).append("\n"); } else { sb.append(2 * n - rem).append("\n"); } } System.out.print(sb.toString()); } }